#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define PI 3.14159265358979323846
#include "dsp_extract.h"   /* generated by run.sh from the DSP-BEGIN/END region of src/EDIT.C */
static int f;
#define CK(c) do{ if(!(c)){printf("FAIL line %d: %s\n",__LINE__,#c);f++;} }while(0)
#define FS 44100.0
static double rms(short*d,long a,long b){ double s=0; for(long i=a;i<b;i++) s+=(double)d[i]*d[i]; return sqrt(s/(b-a)); }
static void sine(short*d,long n,double hz,double amp){ for(long i=0;i<n;i++) d[i]=(short)lrint(amp*sin(2*PI*hz*i/FS)); }
static double ratio(short*in,short*out,long a,long b){ return rms(out,a,b)/rms(in,a,b); }
int main(void){
 long N=44100; short*x=malloc(N*2),*y=malloc(N*2);
 /* low-pass 1 kHz */
 sine(x,N,100,10000); memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,0); double lo100=ratio(x,y,4410,N);
 sine(x,N,10000,10000); memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,0); double lo10k=ratio(x,y,4410,N);
 sine(x,N,1000,10000); memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,0); double lo1k=ratio(x,y,4410,N);
 printf("LP 100Hz %.3f  1kHz %.3f  10kHz %.3f\n",lo100,lo1k,lo10k);
 CK(lo100>0.95); CK(lo10k<0.2); CK(lo1k>0.6&&lo1k<0.8);          /* -3 dB = 0.707 at the cutoff */
 /* high-pass 1 kHz */
 sine(x,N,100,10000); memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,1); double hi100=ratio(x,y,4410,N);
 sine(x,N,10000,10000); memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,1); double hi10k=ratio(x,y,4410,N);
 sine(x,N,1000,10000); memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,1); double hi1k=ratio(x,y,4410,N);
 printf("HP 100Hz %.3f  1kHz %.3f  10kHz %.3f\n",hi100,hi1k,hi10k);
 CK(hi100<0.15); CK(hi10k>0.85); CK(hi1k>0.6&&hi1k<0.8);
 /* DC: LP passes it, HP removes it; no click at the start */
 for(long i=0;i<N;i++) x[i]=12000; memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,0); CK(y[0]==12000&&y[N-1]==12000);
 memcpy(y,x,N*2); onepole_filter(y,N,1000,FS,1); CK(y[0]==0&&abs(y[N-1])<2);
 /* never wraps: full-scale square through high-pass stays in range (clamped) */
 for(long i=0;i<N;i++) x[i]=((i/50)&1)?32767:-32768; memcpy(y,x,N*2); onepole_filter(y,N,3000,FS,1); CK(1);
 /* empty / tiny */ onepole_filter(y,0,1000,FS,0); onepole_filter(y,1,1000,FS,1);
 /* ---- gate: 1000-sample loud burst, then quiet noise ---- */
 long B=1000, T=20000; short*g=malloc(T*2),*o=malloc(T*2); srand(1);
 for(long i=0;i<T;i++) g[i]=(i<B)?(short)lrint(20000*sin(2*PI*220*i/FS)):(short)(rand()%1001-500);
 memcpy(o,g,T*2); double th=0.10*32767, att=1.0*FS/1000, dec=20.0*FS/1000;   /* 10%, 1 ms, 20 ms */
 gate_filter(o,T,th,att,dec);
 int amplified=0; for(long i=0;i<T;i++) if(abs(o[i])>abs(g[i])) amplified=1; CK(!amplified);
 /* inside the burst (after the signal first crosses the threshold and the 1 ms attack ramp) the signal passes unchanged, incl. zero crossings */
 int bad=0; for(long i=70;i<B;i++) if(o[i]!=g[i]) bad++; CK(bad==0);
 /* long after the burst + hold + fade the quiet noise is gated to silence */
 long tail=B+(long)(2*dec)+50; int nz=0; for(long i=tail;i<T;i++) if(o[i]!=0) nz++; CK(nz==0);
 /* and it fades rather than cutting: just after the hold the output is attenuated but not zero */
 long mid=B+(long)dec+(long)(dec/2); CK(abs(o[mid])<abs(g[mid])||g[mid]==0);
 /* quiet-only input: everything gated off from the start */
 for(long i=0;i<T;i++) g[i]=(short)(rand()%401-200); memcpy(o,g,T*2); gate_filter(o,T,th,att,dec); int any=0; for(long i=0;i<T;i++) if(o[i]) any=1; CK(!any);
 /* threshold 0 = always open: input unchanged */
 memcpy(o,g,T*2); gate_filter(o,T,0.0,att,dec); CK(!memcmp(o,g,T*2));
 /* degenerate params don't divide by zero or blow up */
 memcpy(o,g,T*2); gate_filter(o,T,th,0.0,0.0); gate_filter(o,0,th,1,1); gate_filter(o,1,th,1,1);
 printf(f?"FAILED\n":"all passed\n"); return f; }
